import type { ExpressionSpecification } from 'maplibre-gl';

/**
 * Label faces. MapLibre draws text from signed-distance-field glyph ranges, not
 * CSS web fonts, so each stack named here is generated by
 * scripts/buildAtlasGlyphs.mjs into public/atlas/fonts (see its source.json
 * for the pinned fonts and licences). Atlas Serif derives from Libre
 * Baskerville, a text-size transitional serif close to the Scotch-roman
 * lettering engraved on Fletcher's sheets, and sets every name in the Fletcher
 * style; Atlas Sans derives from Noto Sans and sets the modern Day and Night
 * styles and road names everywhere. The Hand-drawn style letters regional names
 * in Atlas Quill (IM Fell English, an old book face) and switches to Atlas Hand
 * (Kalam, a felt-pen hand) at the local scale. The stacks carry project names
 * because converted glyphs are Modified Versions under the OFL.
 */
export const atlasFonts = {
  serif: 'Atlas Serif Regular',
  serifItalic: 'Atlas Serif Italic',
  sans: 'Atlas Sans Regular',
  sansBold: 'Atlas Sans Bold',
  quill: 'Atlas Quill Regular',
  quillItalic: 'Atlas Quill Italic',
  hand: 'Atlas Hand Regular',
  handBold: 'Atlas Hand Bold',
} as const;

/** Glyph ranges are served with the app, including beneath KinNoKi's hosting path. */
export function atlasGlyphUrl(base: string = document.baseURI) {
  return `${new URL('atlas/fonts/', base).href}{fontstack}/{range}.pbf`;
}

/** Paper grain, shore stipple and the hand-inked stroke; see scripts/buildAtlasSprite.mjs. */
export function atlasSpriteUrl(base: string = document.baseURI) {
  return new URL('atlas/sprite/sprite', base).href;
}

/**
 * Feature selections shared by every Atlas style. They read the provincial
 * source fields (NSRN road class, NSTDB feature descriptions) without altering
 * them; each style only decides how the selected features are drawn.
 */
/** One polygon across the whole map carries the paper texture above the fills. */
export const paperSheet: GeoJSON.Feature<GeoJSON.Polygon> = { type: 'Feature', properties: {},
  geometry: { type: 'Polygon', coordinates: [[[-180, -85], [180, -85], [180, 85], [-180, 85], [-180, -85]]] } };

export const roadClass: ExpressionSpecification = ['coalesce', ['get', 'roadc_desc'], ''];
export const description: ExpressionSpecification = ['coalesce', ['get', 'feat_desc'], ''];
const lowerDescription: ExpressionSpecification = ['downcase', description];
export const abandoned: ExpressionSpecification = ['in', 'abandoned', lowerDescription];
export const nonOrdinary: ExpressionSpecification = ['any', abandoned,
  ['in', 'no vehicular traffic', lowerDescription], ['in', 'status unknown', lowerDescription]];
export const majorRoads = ['Trans Canada', 'Highway', 'Local Highway', 'Arterial'];
export const secondaryRoads = ['Collector', 'Local Arterial', 'Local Collector', 'Ramp'];
export const ordinaryRoad: ExpressionSpecification = ['all', ['!', nonOrdinary],
  ['match', roadClass, [...majorRoads, ...secondaryRoads, 'Local'], true, false]];
export const trackClasses = ['Track', 'Trail', 'Driveway', 'Dryweather', 'Seasonal', 'Private Use', 'Restricted', 'Service Lane', 'Water Access', 'Median Crossover'];
// NSRN also fills STREET with class placeholders for unnamed access features.
// Keep those source values in the tiles, but do not print them as road names.
export const genericStreetNames = ['Track', 'Driveway', 'Dryweather', 'Trail', 'Railroad',
  'Active Rail Road', 'Abandoned Rail Road', 'Service Lane', 'Seasonal', 'Private Use',
  'Restricted', 'Water Access', 'Median Crossover', 'Ramp', 'Local', 'Collector',
  'Arterial', 'Highway', 'Trans Canada', 'Local Highway', 'Local Arterial', 'Local Collector'];

export const streams = ['River - Single Line', 'River - Single Line Indefinite', 'River Split - Single Line',
  'River Split - Single Line Indefinite', 'Canal - Single Line', 'Ditch - Single Line', 'Ditch - Single Line Indefinite'];
export const surfaceWater: ExpressionSpecification = ['all', ['in', 'Water', description], ['!', ['in', 'Underground', description]]];
/**
 * NSTDB shoreline lines (present from z11) carry which side the water lies on,
 * so shore treatments can follow real shores. Water polygons are tiled pieces
 * whose shared edges are not shores, so they are never outlined.
 */
const shoreLines = ['Coast - Water to the right line', 'Coastline Indefinite - Water to the right line',
  'Coastal Island - Water to the right line', 'Coastal Island Indefinite - Water to the right line',
  'Coast River - Water to the right line', 'Coast River Island - Island to the left line',
  'Lake - Water to the right line', 'Lake Island - Island to the left line', 'Reservoir - Water to the right line',
  'Double Line River - Water to the right line', 'Double Line River - Water to the left line', 'River Island - Island to the left line'];
const waterOnLeft = ['Double Line River - Water to the left line'];
export const shoreFilter: ExpressionSpecification = ['match', description, shoreLines, true, false];
/** Positive offsets move a line to its right; NSTDB names which side is water. */
export const towardWater = (distance: number): ExpressionSpecification => ['match', description, waterOnLeft, -distance, distance];
